    Bug 2052976 - Ensure entries in gEncryptedURIService are cleaned up correctly. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D310721

diff --git a/mail/extensions/openpgp/content/ui/enigmailMsgHdrViewOverlay.js b/mail/extensions/openpgp/content/ui/enigmailMsgHdrViewOverlay.js
index d90f85503a1..e1f1aebb405 100644
--- a/mail/extensions/openpgp/content/ui/enigmailMsgHdrViewOverlay.js
+++ b/mail/extensions/openpgp/content/ui/enigmailMsgHdrViewOverlay.js
@@ -33,6 +33,7 @@ ChromeUtils.defineESModuleGetters(this, {

 Enigmail.hdrView = {
   lastEncryptedUri: null,
+  lastEncryptedNeckoUri: null,

   msgSignedStateString: null,
   msgEncryptedStateString: null,
@@ -233,10 +234,11 @@ Enigmail.hdrView = {

       this.msgSignatureState = EnigmailConstants.MSG_SIG_NONE;
     } else if (statusFlags & EnigmailConstants.DECRYPTION_OKAY) {
-      gEncryptedURIService.rememberEncrypted(this.lastEncryptedUri);
-      gEncryptedURIService.rememberEncrypted(
-        MailServices.neckoURLForMessageURI(this.lastEncryptedUri)
+      this.lastEncryptedNeckoUri = MailServices.neckoURLForMessageURI(
+        this.lastEncryptedUri
       );
+      gEncryptedURIService.rememberEncrypted(this.lastEncryptedUri);
+      gEncryptedURIService.rememberEncrypted(this.lastEncryptedNeckoUri);
       encrypted = "ok";
       this.msgEncryptionState = EnigmailConstants.MSG_ENC_OK;
     }
@@ -372,10 +374,13 @@ Enigmail.hdrView = {
   forgetEncryptedMsgKey() {
     if (Enigmail.hdrView.lastEncryptedUri) {
       gEncryptedURIService.forgetEncrypted(Enigmail.hdrView.lastEncryptedUri);
+      Enigmail.hdrView.lastEncryptedUri = null;
+    }
+    if (Enigmail.hdrView.lastEncryptedNeckoUri) {
       gEncryptedURIService.forgetEncrypted(
-        MailServices.neckoURLForMessageURI(Enigmail.hdrView.lastEncryptedUri)
+        Enigmail.hdrView.lastEncryptedNeckoUri
       );
-      Enigmail.hdrView.lastEncryptedUri = null;
+      Enigmail.hdrView.lastEncryptedNeckoUri = null;
     }
   },

diff --git a/mail/extensions/smime/content/msgHdrViewSMIMEOverlay.js b/mail/extensions/smime/content/msgHdrViewSMIMEOverlay.js
index d889db3b1ed..76ce5ea8405 100644
--- a/mail/extensions/smime/content/msgHdrViewSMIMEOverlay.js
+++ b/mail/extensions/smime/content/msgHdrViewSMIMEOverlay.js
@@ -11,6 +11,7 @@
 /* globals gEncryptedURIService */

 var gMyLastEncryptedURI = null;
+var gMyLastEncryptedNeckoURI = null;

 var gSMIMEBundle = null;

@@ -409,10 +410,10 @@ var smimeSink = {
     if (gEncryptedURIService) {
       // Remember the message URI and the corresponding necko URI.
       gMyLastEncryptedURI = gMessageURI;
+      gMyLastEncryptedNeckoURI =
+        MailServices.neckoURLForMessageURI(gMyLastEncryptedURI);
       gEncryptedURIService.rememberEncrypted(gMyLastEncryptedURI);
-      gEncryptedURIService.rememberEncrypted(
-        MailServices.neckoURLForMessageURI(gMyLastEncryptedURI)
-      );
+      gEncryptedURIService.rememberEncrypted(gMyLastEncryptedNeckoURI);
     }

     switch (aEncryptionStatus) {
@@ -459,11 +460,12 @@ var smimeSink = {
 function forgetEncryptedURI() {
   if (gMyLastEncryptedURI && gEncryptedURIService) {
     gEncryptedURIService.forgetEncrypted(gMyLastEncryptedURI);
-    gEncryptedURIService.forgetEncrypted(
-      MailServices.neckoURLForMessageURI(gMyLastEncryptedURI)
-    );
     gMyLastEncryptedURI = null;
   }
+  if (gMyLastEncryptedNeckoURI && gEncryptedURIService) {
+    gEncryptedURIService.forgetEncrypted(gMyLastEncryptedNeckoURI);
+    gMyLastEncryptedNeckoURI = null;
+  }
 }

